// Preparation only: copies exact reviewer controls; starts no installation or model.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
const root=path.dirname(fileURLToPath(import.meta.url)),source=path.resolve(root,'../0-1-4');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const declared=JSON.parse(fs.readFileSync(path.join(source,'frozen-copy-inventory.json'),'utf8'));
const byName=Object.fromEntries(declared.files.map(row=>[row.relative,row]));
const repeatedControl=JSON.parse(fs.readFileSync(path.join(source,'repeated-plan-control.json'),'utf8'));
const records=[];
function exact(relative,target=relative,expected=byName[relative]?.sha256){
 const from=path.join(source,relative),to=path.join(root,target),bytes=fs.readFileSync(from),sha=hash(bytes);
 if(expected&&sha!==expected)throw new Error('Source frozen bytes changed: '+relative);
 if(fs.existsSync(to))throw new Error('Do not overwrite prepared controls: '+target);
 fs.mkdirSync(path.dirname(to),{recursive:true});fs.writeFileSync(to,bytes,{flag:'wx'});
 if(hash(fs.readFileSync(to))!==sha)throw new Error('Copied bytes differ: '+target);
 records.push({relative:target,source:from,bytes:bytes.length,sha256:sha,sourceDeclaredSha256:expected??null,verification:expected?'MATCH_DECLARED_AND_SOURCE_BYTES':'MATCH_CURRENT_SOURCE_BYTES',operation:'EXACT_COPY'});
 return bytes;
}
for(const kind of ['blocking','expanded','continuous-supplement']){
 for(const name of ['harness.mjs','plan.json','frozen-spec.md','choose-first.mjs','record-native-loading.mjs','operator-observations.mjs'])exact(kind+'/'+name);
 if(kind!=='blocking')exact(kind+'/expanded-plan.mjs');
}
exact('expanded/criterion-citation-erratum.json');
exact('expanded/repeated-plan.json','expanded/repeated-plan.json',repeatedControl.newPlanSha256);
exact('repeated-plan-control.json');
exact('operator-sequential.manual.mjs','operator-sequential.manual.mjs',repeatedControl.operatorAfterSha256);
exact('operator-sequential.manual.before-declared-plan.mjs','provenance/operator-sequential.manual.before-declared-plan.0-1-4.mjs',repeatedControl.operatorBeforeSha256);
exact('frozen-copy-inventory.json','provenance/frozen-copy-inventory.0-1-4.json');
const guardChanges=[];
for(const relative of ['prepare-correction.mjs','verify-canonical.mjs']){
 const before=exact(relative,'provenance/'+relative.replace('.mjs','.0-1-4.mjs'));
 const text=before.toString('utf8'),occurrences=[...text.matchAll(/0\.1\.4/g)].map(match=>match.index);
 if(!occurrences.length)throw new Error('Expected version guard absent: '+relative);
 const after=Buffer.from(text.replaceAll('0.1.4','0.1.5'));
 const to=path.join(root,relative);if(fs.existsSync(to))throw new Error('Do not overwrite new guard');
 fs.writeFileSync(to,after,{flag:'wx'});
 if(after.length!==before.length)throw new Error('Version-only guard length changed');
 const changedByteOffsets=[];for(let i=0;i<before.length;i++)if(before[i]!==after[i])changedByteOffsets.push(i);
 if(changedByteOffsets.length!==occurrences.length||changedByteOffsets.some(i=>before[i]!==52||after[i]!==53))throw new Error('Unexpected guard mutation');
 const row={relative,source:path.join(source,relative),beforeSha256:hash(before),afterSha256:hash(after),beforeBytes:before.length,afterBytes:after.length,change:'Only 0.1.4 -> 0.1.5 literals',occurrenceCount:occurrences.length,changedByteOffsets};
 guardChanges.push(row);records.push({relative,source:row.source,bytes:after.length,sha256:row.afterSha256,operation:'VERSION_GUARD_ONLY',beforeSha256:row.beforeSha256});
}
const kinds=Object.fromEntries(['blocking','expanded','continuous-supplement'].map(kind=>{const plan=JSON.parse(fs.readFileSync(path.join(root,kind,'plan.json'),'utf8'));return[kind,{freshVariants:plan.freshVariants,plannedTurns:plan.plannedTurns,materialHashes:Object.fromEntries(Object.entries(plan.materials).map(([name,value])=>[name,hash(Buffer.from(value))])),variants:plan.variants.map(v=>({id:v.id,base:v.base,runnable:v.runnable!==false,turns:v.turns.map((text,index)=>({turn:index+1,sha256:hash(Buffer.from(text))}))}))}];}));
const inventory={createdAt:new Date().toISOString(),phase:'PREPARATION_ONLY_WAITING_FOR_PARENT_CANONICAL_AND_STRICT_INSTALLATION',candidateVersion:'0.1.5',canonical:null,installationInvoked:false,modelInvoked:false,oldDirectoriesModified:false,files:records,guardChanges,plans:kinds,manualSelection:{operator:'operator-sequential.manual.mjs',sha256:hash(fs.readFileSync(path.join(root,'operator-sequential.manual.mjs'))),readsBatchDeclaredPlan:true,chooseFirstExecutionForbidden:true,copiedChooseFirstPurpose:'Historical exact dependency retained only; never execute it.',requiresActualTargetHeadingAndSingleTripletExactExcerpt:true,normalBoundaryPauseOnly:true},historicalSourceInventoryNote:'0.1.4 frozen-copy inventory recorded the pre-declared-plan manual operator. The current operator matches the exact after SHA in 0.1.4 repeated-plan-control.json; both original and revised bytes are retained.',effectStatus:'NOT_MEASURED',semanticStatus:'NOT_RUN'};
fs.writeFileSync(path.join(root,'frozen-copy-inventory.json'),JSON.stringify(inventory,null,2)+'\n',{flag:'wx'});
